@namespace sv_7161118fbecf4c0080fc17b79de56ff1.Components.Pages.Apply

<div class="reference-card">
    <div class="reference-header">
        <h4>Reference @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Name *</label>
        <input type="text" class="form-control" value="@Reference.Name"
               @onchange="e => Update(Reference with { Name = e.Value?.ToString() ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Relationship *</label>
        <input type="text" class="form-control" value="@Reference.Relationship"
               @onchange="e => Update(Reference with { Relationship = e.Value?.ToString() ?? string.Empty })" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email *</label>
            <input type="email" class="form-control" value="@Reference.Email"
