{"path": "/tmp/sv-7161118fbecf4c0080fc17b79de56ff1/Components/Pages/Apply/WorkHistoryStep.razor", "file_text": "@namespace sv_7161118fbecf4c0080fc17b79de56ff1.Components.Pages.Apply

<div class="step-content">
