@namespace sv_7161118fbecf4c0080fc17b79de56ff1.Components.Pages.Apply

<div class="step-content">
    <h3>Personal Information</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" class="form-control" value="@Personal.FullName"
               @onchange="e => UpdateField(Personal with { FullName = e.Value?.ToString() ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Email *</label>
        <input type="email" class="form-control" value="@Personal.Email"
               @onchange="e => UpdateField(Personal with { Email = e.Value?.ToString() ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" class="form-control" value="@Personal.Phone"
               @onchange="e => UpdateField(Personal with { Phone = e.Value?.ToString() ?? string.Empty })" />
    </div>

    <div class="form-group">
        <label>Address *</label>
        <textarea class="form-control" rows="2" value="@Personal.Address"
                  @onchange="e => UpdateField(Personal with { Address = e.Value?.ToString() ?? string.Empty })"></textarea>
    </div>

    <div class="step-actions">
        <button type="button" class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @(IsValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfo Personal { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<PersonalInfo> OnPersonalChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public Func<string, Task<bool>> ValidateEmail { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidating;

    private async Task UpdateField(PersonalInfo updated)
    {
        await OnPersonalChanged.InvokeAsync(updated);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Personal.FullName) ||
            string.IsNullOrWhiteSpace(Personal.Email) ||
            string.IsNullOrWhiteSpace(Personal.Phone) ||
            string.IsNullOrWhiteSpace(Personal.Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsValidating = true;
        try
        {
            var isValidEmail = await ValidateEmail(Personal.Email);
            if (!isValidEmail)
            {
                ErrorMessage = "The email address is not valid.";
                return;
            }
            await OnNext.InvokeAsync();
        }
        finally
        {
            IsValidating = false;
        }
    }
}

