@namespace sv_7161118fbecf4c0080fc17b79de56ff1.Components.Pages.Apply

<div class="step-content">
    <h3>References</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="@References[index]"
                       Index="index"
                       CanRemove="@(References.Count > 2)"
                       OnReferenceChanged="e => UpdateReference(index, e)"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    <div class="step-actions">
        <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Reference> References { get; set; } = default!;
    [Parameter, EditorRequired] public EventCallback<List<Reference>> OnReferencesChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private async Task UpdateReference(int index, Reference updated)
    {
        var list = new List<Reference>(References);
        list[index] = updated;
        await OnReferencesChanged.InvokeAsync(list);
    }

    private async Task RemoveReference(int index)
    {
        var list = new List<Reference>(References);
        list.RemoveAt(index);
        await OnReferencesChanged.InvokeAsync(list);
    }

    private async Task AddReference()
    {
        if (References.Count < 3)
        {
            var list = new List<Reference>(References)
            {
                new(string.Empty, string.Empty, string.Empty, string.Empty)
            };
            await OnReferencesChanged.InvokeAsync(list);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (References.Count < 2)
        {
            ErrorMessage = "Please provide at least 2 references.";
            return;
        }

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) || string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Each reference must have a name, relationship, and email.";
