@namespace sv_7161118fbecf4c0080fc17b79de56ff1.Components.Pages.Apply

<div class="step-content">
    <h3>Cover Letter</h3>

    @if (!string.IsNullOrEmpty(ErrorMessage))
    {
        <div class="alert alert-danger">@ErrorMessage</div>
    }

    <div class="form-group">
        <textarea class="form-control cover-letter-textarea" rows="12" maxlength="2000"
                  value="@CoverLetter"
                  @oninput="HandleInput"></textarea>
        <div class="character-count">@CoverLetter.Length / 2000 characters</div>
    </div>

    <div class="step-actions">
        <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
        <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string CoverLetter { get; set; } = string.Empty;
    [Parameter, EditorRequired] public EventCallback<string> OnCoverLetterChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? string.Empty;
        if (value.Length <= 2000)
        {
            await OnCoverLetterChanged.InvokeAsync(value);
        }
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ErrorMessage = "Please write a cover letter.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

