@page "/apply"
@using sv_7161118fbecf4c0080fc17b79de56ff1.Models
@using sv_7161118fbecf4c0080fc17b79de56ff1.Components.Pages.Apply

@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="application-container">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="@currentStep"
                   CompletedSteps="@completedSteps"
                   OnStepSelected="GoToStep" />

    @switch (currentStep)
    {
        case 0:
            <PersonalInfoStep Personal="@personalInfo"
                              OnPersonalChanged="p => personalInfo = p"
                              OnNext="NextStep"
                              ValidateEmail="ValidateEmailAsync" />
            break;
        case 1:
            <WorkHistoryStep Entries="@workEntries"
                             OnEntriesChanged="e => workEntries = e"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 2:
            <ReferencesStep References="@references"
                            OnReferencesChanged="r => references = r"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;
        case 3:
            <CoverLetterStep CoverLetter="@coverLetter"
                             OnCoverLetterChanged="c => coverLetter = c"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;
        case 4:
            <ReviewStep Personal="@personalInfo"
                        WorkEntries="@workEntries"
                        References="@references"
                        CoverLetter="@coverLetter"
                        OnEditStep="GoToStep"
                        OnBack="PreviousStep"
                        SubmitApplication="SubmitAsync" />
            break;
    }
</div>

@code {
    [Inject] private IApplicationService ApplicationService { get; set; } = default!;

    private int currentStep = 0;
    private HashSet<int> completedSteps = new();

    private PersonalInfo personalInfo = new(string.Empty, string.Empty, string.Empty, string.Empty);
    private List<WorkEntry> workEntries = new() { new(string.Empty, string.Empty, DateTime.Today, null, string.Empty) };
    private List<Reference> references = new()
    {
        new(string.Empty, string.Empty, string.Empty, string.Empty),
        new(string.Empty, string.Empty, string.Empty, string.Empty)
    };
    private string coverLetter = string.Empty;

    private void NextStep()
    {
        completedSteps.Add(currentStep);
        currentStep++;
    }

    private void PreviousStep()
    {
        currentStep--;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private async Task<bool> ValidateEmailAsync(string email)
    {
        return await ApplicationService.ValidateEmailAsync(email);
    }

    private async Task<int> SubmitAsync()
    {
        var application = new JobApplication(
            personalInfo,
            new WorkHistory(workEntries),
            references,
            coverLetter
        );
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

