@using sv_7161118fbecf4c0080fc17b79de56ff1.Models
@namespace sv_7161118fbecf4c0080fc17b79de56ff1.Components.Pages.Apply

<div class="work-entry-card">
    <div class="work-entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (CanRemove)
        {
            <button type="button" class="btn btn-danger btn-sm" @onclick="OnRemove">Remove</button>
        }
    </div>

    <div class="form-group">
        <label>Company Name *</label>
        <input type="text" class="form-control" value="@Entry.Company"
               @onchange="HandleCompanyChange" />
    </div>

    <div class="form-group">
        <label>Job Title *</label>
        <input type="text" class="form-control" value="@Entry.Title"
               @onchange="HandleTitleChange" />
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date *</label>
            <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                   @onchange="HandleStartDateChange" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" class="form-control" value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty)"
                   disabled="@IsCurrent"
                   @onchange="HandleEndDateChange" />
        </div>
    </div>

    <div class="form-group form-check">
        <input type="checkbox" class="form-check-input" id="@CurrentCheckboxId" checked="@IsCurrent"
               @onchange="HandleCurrentToggle" />
        <label class="form-check-label" for="@CurrentCheckboxId">I currently work here</label>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea class="form-control" rows="3" value="@Entry.Description"
                  @onchange="HandleDescriptionChange"></textarea>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public WorkEntry Entry { get; set; } = default!;
    [Parameter, EditorRequired] public int Index { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter, EditorRequired] public EventCallback<WorkEntry> OnEntryChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate == null && Entry.StartDate != default;
    private string CurrentCheckboxId => $"current-{Index}";

    private Task HandleCompanyChange(ChangeEventArgs e)
    {
        return OnEntryChanged.InvokeAsync(
            new WorkEntry(e.Value?.ToString() ?? string.Empty, Entry.Title, Entry.StartDate, Entry.EndDate, Entry.Description));
    }

    private Task HandleTitleChange(ChangeEventArgs e)
    {
        return OnEntryChanged.InvokeAsync(
            new WorkEntry(Entry.Company, e.Value?.ToString() ?? string.Empty, Entry.StartDate, Entry.EndDate, Entry.Description));
    }

    private Task HandleStartDateChange(ChangeEventArgs e)
    {
        var date = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : DateTime.Today;
        return OnEntryChanged.InvokeAsync(
            new WorkEntry(Entry.Company, Entry.Title, date, Entry.EndDate, Entry.Description));
    }

    private Task HandleEndDateChange(ChangeEventArgs e)
    {
        var val = e.Value?.ToString();
        DateTime? endDate = string.IsNullOrEmpty(val) ? null : DateTime.Parse(val);
        return OnEntryChanged.InvokeAsync(
            new WorkEntry(Entry.Company, Entry.Title, Entry.StartDate, endDate, Entry.Description));
    }

    private Task HandleCurrentToggle(ChangeEventArgs e)
    {
        var isCurrent = (bool)(e.Value ?? false);
        DateTime? endDate = isCurrent ? null : DateTime.Today;
        return OnEntryChanged.InvokeAsync(
            new WorkEntry(Entry.Company, Entry.Title, Entry.StartDate, endDate, Entry.Description));
    }

    private Task HandleDescriptionChange(ChangeEventArgs e)
    {
        return OnEntryChanged.InvokeAsync(
            new WorkEntry(Entry.Company, Entry.Title, Entry.StartDate, Entry.EndDate, e.Value?.ToString() ?? string.Empty));
    }
}

